// Confidence Evaluator Node (n8n Code Node)
// Evalúa la puntuación de confianza de la IA contra la Matriz de Permisos (Umbral L2 = 85%)

for (const item of $input.all()) {
  const payload = item.json;

  // Extraer la puntuación de confianza (número del 0 al 100)
  const confidence = Number(payload.confidence || 0);
  const sampleCode = payload.sample_code || 'UNKNOWN';
  const technique = payload.technique || 'ICP';

  // Umbral oficial de la Matriz de Permisos L2
  const CONFIDENCE_THRESHOLD = 85;

  if (confidence >= CONFIDENCE_THRESHOLD) {
    // Nivel L4 (AUTÓNOMO): Pasa directo a guardar en PostgreSQL
    item.json.verdict = 'ALLOW';
    item.json.autonomy_level = 'L4';
    item.json.requires_human_approval = false;
    item.json.status_message = `HIGH_CONFIDENCE (${confidence}%): Autonomous insertion granted.`;
  } else {
    // Nivel L2 (PIDE OK): Se desvía al correo para aprobación humana
    item.json.verdict = 'REQUIRE_APPROVAL';
    item.json.autonomy_level = 'L2';
    item.json.requires_human_approval = true;
    item.json.status_message = `LOW_CONFIDENCE (${confidence}% < ${CONFIDENCE_THRESHOLD}%): Human approval required.`;

    // Preparar el cuerpo del mensaje para el correo
    item.json.approval_email_subject = `[ALCheMy L2 Approval Required] Low Confidence PDF Ingestion (${sampleCode})`;
    item.json.approval_email_body = `Action Required by Rubén S.N.:\n\nThe AI Agent extracted chemical data for sample ${sampleCode} (${technique}), but confidence score was ${confidence}% (Threshold: ${CONFIDENCE_THRESHOLD}%).\n\nAI Reasoning: ${payload.reasoning || 'N/A'}\n\nPlease click Approval or Rejection button below.`;
  }
}

return $input.all();

