for (const item of $input.all()) {
  if (item.json.sample_code) {
    item.json.sample_code = String(item.json.sample_code).trim().toUpperCase().replace(/[^A-Z0-9_-]/g, '');
  }
  if (item.json.researcher_email) {
    item.json.researcher_email = String(item.json.researcher_email).trim().toLowerCase();
  }
  if (item.json.operator_name) {
    item.json.operator_name = String(item.json.operator_name).trim();
  }
}
return $input.all();

for (const item of $input.all()) {
  // 1. Buscar el item dinámico en los nodos de origen (Formulario, Disco o Webhook)
  const sourceItem = $("Sanitize Input").item || $("Extract Technique from Path").item || item;
  const binaryData = sourceItem.binary?.data_file || sourceItem.binary?.data;

  // 2. Extraer el nombre real dinámico del archivo recibido
  const fileName = binaryData?.fileName || sourceItem.json?.fileName || sourceItem.json?.data_file?.[0]?.filename || sourceItem.json?.name || '';
  const fileExt = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';

  // 3. Inyectar metadatos dinámicos
  item.json.file_name = fileName;
  item.json.file_ext = fileExt;
  item.json.is_archive = (fileExt === 'zip' || fileExt === 'rar');
}
return $input.all();

// Node 2: Calculate MD5 File Hash (Generador de Huella Antiduplicado)
const crypto = require('crypto');
for (const item of $input.all()) {
  const sourceItem = $("Sanitize Input").item || $("Extract Technique from Path").item || item;
  const binaryData = sourceItem.binary?.data_file || sourceItem.binary?.data;

  if (binaryData && binaryData.data) {
    const buffer = Buffer.from(binaryData.data, 'base64');
    item.json.file_hash = crypto.createHash('md5').update(buffer).digest('hex');
  } else {
    item.json.file_hash = 'hash_' + Date.now();
  }
}
return $input.all();
